40	    using var doc = await JsonDocument.ParseAsync(req.Body); var r = doc.RootElement;
41	    var id = r.GetProperty("id").GetString()!;
42	    var order = new Order(r.TryGetProperty("shipped", out var s) && s.GetBoolean(), r.TryGetProperty("paid", out var p) && p.GetBoolean(), false);
