66	        return Results.Json(new { ok = false, reason = "not_found", request_id = rid }, statusCode: 404);
67	    }
68	    var result = Cancellation.Cancel(before);
69	    bool transitioned = Cancellation.Transitioned(before, result);
70	    string outcome; int status;
71	    if (before.Shipped) { outcome = "rejected_shipped"; status = 409; }          // BR-02，不通知（NC-03）
72	    else if (transitioned) { outcome = "ok"; status = 200; store.Put(id, result.Order); }
